package com.techconsulting.lending.service;
import com.techconsulting.lending.domain.*; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.time.*; import static org.assertj.core.api.Assertions.*;
class LoanCalculationServiceTest { private LoanReportStaging row(){var r=new LoanReportStaging();r.setSchemeId("L1");r.setInvestedAmount(new BigDecimal("1000"));r.setAmountReceived(new BigDecimal("450"));r.setTenure(new BigDecimal("4"));r.setInvestmentDate(LocalDate.of(2026,8,1));r.setLoanStatus("ACTIVE");r.setDpd(0);return r;} @Test void separatesPrincipalAndInterest(){var out=new LoanCalculationService(Clock.fixed(Instant.parse("2026-09-01T00:00:00Z"),ZoneOffset.UTC),false).calculate(1L,1L,row(),new ManualLending());assertThat(out.getPrincipalEmi()).isEqualByComparingTo("250.00");assertThat(out.getCalculatedPrincipalReceived()).isEqualByComparingTo("250.00");assertThat(out.getCalculatedInterestReceived()).isEqualByComparingTo("200.00");assertThat(out.getOutstandingPrincipal()).isEqualByComparingTo("750.00");} @Test void closedLossIsNpa(){var r=row();r.setLoanStatus("CLOSED");var out=new LoanCalculationService(Clock.systemUTC(),false).calculate(1L,1L,r,new ManualLending());assertThat(out.isNpa()).isTrue();assertThat(out.getNpaReason()).isEqualTo("CLOSED_BEFORE_PRINCIPAL_RECOVERY");assertThat(out.getReturnAmount()).isEqualByComparingTo("-550.00");}}
class LoanCalculationServiceTest { private LoanReportStaging row(){var r=new LoanReportStaging();r.setSchemeId("L1");r.setInvestedAmount(new BigDecimal("1000"));r.setAmountReceived(new BigDecimal("450"));r.setTenure(new BigDecimal("4"));r.setInvestmentDate(LocalDate.of(2026,8,1));r.setLoanStatus("ACTIVE");r.setDpd(0);return r;} @Test void separatesPrincipalAndInterest(){var out=new LoanCalculationService(Clock.fixed(Instant.parse("2026-09-01T00:00:00Z"),ZoneOffset.UTC),false).calculate(1L,1L,row(),new ManualLending());assertThat(out.getPrincipalEmi()).isEqualByComparingTo("250.00");assertThat(out.getCalculatedPrincipalReceived()).isEqualByComparingTo("250.00");assertThat(out.getCalculatedInterestReceived()).isEqualByComparingTo("200.00");assertThat(out.getOutstandingPrincipal()).isEqualByComparingTo("750.00");} @Test void usesReportedPrincipalAndInterestWhenAvailable(){var r=row();r.setReportedPrincipalReceived(new BigDecimal("400"));r.setReportedInterestReceived(new BigDecimal("50"));var out=new LoanCalculationService(Clock.systemUTC(),false).calculate(1L,1L,r,new ManualLending());assertThat(out.getCalculatedPrincipalReceived()).isEqualByComparingTo("400.00");assertThat(out.getCalculatedInterestReceived()).isEqualByComparingTo("50.00");assertThat(out.getOutstandingPrincipal()).isEqualByComparingTo("600.00");} @Test void closedLossIsNpa(){var r=row();r.setLoanStatus("CLOSED");var out=new LoanCalculationService(Clock.systemUTC(),false).calculate(1L,1L,r,new ManualLending());assertThat(out.isNpa()).isTrue();assertThat(out.getNpaReason()).isEqualTo("CLOSED_BEFORE_PRINCIPAL_RECOVERY");assertThat(out.getReturnAmount()).isEqualByComparingTo("-550.00");} @Test void preservesReportedNpaStatus(){var r=row();r.setLoanStatus("NPA");var out=new LoanCalculationService(Clock.systemUTC(),false).calculate(1L,1L,r,new ManualLending());assertThat(out.getLoanStatus()).isEqualTo("NPA");assertThat(out.isNpa()).isTrue();assertThat(out.getNpaReason()).isEqualTo("REPORTED_AS_NPA");}}
